import SwiftUI
import UIKit

/// Stretch applied between Clip min (x = 0) and Clip max (x = 1), same definitions as CARTA.
nonisolated enum ScalingType: String, CaseIterable, Identifiable {
    case linear, log, sqrt, squared, gamma, power

    var id: Self { self }

    var title: String {
        switch self {
        case .linear: "Linear"
        case .log: "Log"
        case .sqrt: "Square Root"
        case .squared: "Squared"
        case .gamma: "Gamma"
        case .power: "Power"
        }
    }

    var formula: String {
        switch self {
        case .linear: "y = x"
        case .log: "y = log(αx + 1) / log(α + 1)"
        case .sqrt: "y = √x"
        case .squared: "y = x²"
        case .gamma: "y = x^γ"
        case .power: "y = (αˣ − 1) / (α − 1)"
        }
    }

    var usesAlpha: Bool { self == .log || self == .power }

    func apply(_ x: Double, alpha: Double, gamma: Double) -> Double {
        switch self {
        case .linear: return x
        case .log: return log1p(alpha * x) / log1p(alpha)
        case .sqrt: return x.squareRoot()
        case .squared: return x * x
        case .gamma: return pow(x, gamma)
        case .power: return (pow(alpha, x) - 1) / (alpha - 1)
        }
    }
}

nonisolated enum Colormap: String, CaseIterable, Identifiable {
    case inferno, magma, plasma, viridis, cividis, gray, hot, jet, coolwarm, cubehelix, tab10

    var id: Self { self }
    var title: String { rawValue }

    /// 256 colors per map, packed 0xRRGGBB.
    private static let tables: [Colormap: [UInt32]] =
        Dictionary(uniqueKeysWithValues: Colormap.allCases.map { ($0, $0.buildTable()) })

    /// 256-entry lookup table packed for an RGBA8 bitmap (bytes R, G, B, A in memory).
    func lut(inverted: Bool) -> [UInt32] {
        let colors = Colormap.tables[self] ?? []
        let ordered: [UInt32] = inverted ? colors.reversed() : colors
        return ordered.map { rgb in
            let r = (rgb >> 16) & 0xFF, g = (rgb >> 8) & 0xFF, b = rgb & 0xFF
            return r | (g << 8) | (b << 16) | 0xFF00_0000
        }
    }

    /// A 256×1 strip of the colormap for swatches.
    func swatchImage(inverted: Bool) -> UIImage? {
        FITSRenderer.makeImage(pixels: lut(inverted: inverted), width: 256, height: 1)
    }

    private func buildTable() -> [UInt32] {
        switch self {
        case .gray:
            return (0..<256).map { UInt32($0) * 0x010101 }
        case .tab10:
            let t: [UInt32] = [0x1f77b4, 0xff7f0e, 0x2ca02c, 0xd62728, 0x9467bd,
                               0x8c564b, 0xe377c2, 0x7f7f7f, 0xbcbd22, 0x17becf]
            return (0..<256).map { t[min(9, $0 * 10 / 256)] }
        default:
            let bytes = Array(hexTable.utf8)
            func nibble(_ c: UInt8) -> UInt32 {
                switch c {
                case 48...57: return UInt32(c - 48)    // 0-9
                case 97...102: return UInt32(c - 87)   // a-f
                default: return 0
                }
            }
            var out: [UInt32] = []
            out.reserveCapacity(256)
            var i = 0
            while i + 6 <= bytes.count {
                var v: UInt32 = 0
                for k in 0..<6 { v = (v << 4) | nibble(bytes[i + k]) }
                out.append(v)
                i += 6
            }
            return out.count == 256 ? out : (0..<256).map { UInt32($0) * 0x010101 }
        }
    }

    // Exact 256-step tables generated from matplotlib.
    private var hexTable: String {
        switch self {
        case .inferno: return ""
        case .magma: return ""
        case .plasma: return ""
        case .viridis: return ""
        case .cividis: return ""
        case .hot: return ""
        case .jet: return ""
        case .coolwarm: return ""
        case .cubehelix: return ""
        default: return ""
        }
    }
}

nonisolated struct RenderSettings: Equatable {
    var clipMin: Double = 0
    var clipMax: Double = 1
    var scaling: ScalingType = .linear
    var alpha: Double = 1000     // used by Log and Power
    var gamma: Double = 1        // used by Gamma
    var colormap: Colormap = .inferno
    var inverted = false
}

enum ClipSelection: Equatable {
    case percentile(Double)
    case manual

    var title: String {
        switch self {
        case .percentile(let p): ClipSelection.percentText(p)
        case .manual: "Manual"
        }
    }

    static func percentText(_ p: Double) -> String {
        p.formatted(.number.precision(.fractionLength(0...4)).grouping(.never)) + "%"
    }
}
